import {ask} from './confirm.mjs';
import {extraTools,groups,category,mountExtended,calculatorIntegration,clearNewData} from './extended.mjs?v=14.1';
import {calculators,defaults} from './calculators.mjs';
const app=document.querySelector('#app');let filter='All tools',active,values,rows;const key='ap-consulting-tools-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,u)=>v===null||!Number.isFinite(v)?'Not attainable':u==='$'?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v):new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(u==='ceil'?Math.ceil(v):v)+(u&&u!=='ceil'?' '+u:'');
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',3000)}
function persist(){saved[active.id]=values;try{localStorage.setItem(key,JSON.stringify(saved));}catch{toast('Browser storage unavailable; inputs remain in this tab.')}}
function home(){const all=[...calculators,...extraTools];app.innerHTML=`<div class="eyebrow">Your consulting toolkit</div><div class="intro"><div><h1>Clarity in every calculation.</h1><p>Fourteen practical tools to qualify prospects, diagnose businesses,<br>prepare proposals, and explore the numbers.</p></div><div class="count"><strong>14<span class="gold">.</span></strong><span>CONSULTING TOOLS</span></div></div><div class="toolbar"><nav class="filters" aria-label="Filter tools">${['All tools',...groups].map(t=>`<button class="${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</nav></div>${groups.filter(g=>filter==='All tools'||filter===g).map(g=>`<section class="home-group"><h2>${g}</h2><div class="grid">${all.filter(c=>category(c.id)===g).map(c=>`<a class="card" href="#${c.id}"><div class="card-top"><span class="icon" aria-hidden="true">${c.icon}</span><span class="tag">${extraTools.includes(c)?'Consulting tool':'Calculator'}</span></div><h3>${c.name}</h3><p>${c.description}</p><div class="card-bottom"><span>Open tool</span><span aria-hidden="true">↗</span></div></a>`).join('')}</div></section>`).join('')}<aside class="note"><span class="gold">ⓘ</span><p><b>Local tools, informed decisions.</b> Forecasts are estimates, not guarantees. Original calculator examples are fictional. Local CRM Mode is for non-sensitive test data: records stay in this browser, do not sync, and may be lost when browser data is cleared. Export backups regularly.</p></aside>`;app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;home()})}
function render(){if(mountExtended(location.hash.slice(1)))return;try{const d=JSON.parse(localStorage.getItem(key)||'{}');if(d&&typeof d==='object'&&!Array.isArray(d))saved=d;}catch{}active=calculators.find(c=>c.id===location.hash.slice(1));if(!active){home();return}values={...defaults(active),...saved[active.id]};app.innerHTML=`<a class="back" href="#">← All tools</a><div class="eyebrow">${category(active.id)} / Calculator ${String(calculators.indexOf(active)+1).padStart(2,'0')}</div><div class="calc-head"><div><h1>${active.name}</h1><p>${active.description}</p></div><div class="actions"><button id="reset">Reset</button><button id="copy">Copy results ↗</button></div></div><div class="calculator"><section class="panel"><h2>Your assumptions</h2>${active.id==='launch'?`<label class="preset">Package preset<select id="preset"><option value="">Choose a package (price remains editable)</option>${[['Launch Essentials',499],['Launch Concierge Introductory',999],['Launch Concierge Standard',1499],['Launch & Grow',2999]].map(([n,v])=>`<option value="${v}">${n} — ${fmt(v,'$')}</option>`).join('')}</select></label>`:''}${active.id==='capacity'?`<label class="select-period">Calculation period<select id="period"><option value="weekly" ${values.period==='weekly'?'selected':''}>Weekly — hours per week</option><option value="monthly" ${values.period==='monthly'?'selected':''}>Monthly — hours per month</option></select></label>`:''}<div class="fields">${active.fields.map(f=>`<label>${f.label}${active.id==='capacity'&&f.unit==='hours'?' ('+(values.period==='monthly'?'per month':'per week')+')':''}<div class="input-wrap"><input type="number" step="any" min="${['s','i'].includes(f.key)&&active.id==='cash'||['c','v'].includes(f.key)&&active.id==='roi'?'-1000000000000':'0'}" ${f.max!==undefined?'max="'+f.max+'"':''} data-key="${f.key}" value="${esc(values[f.key])}"><span class="unit">${f.unit}</span></div></label>`).join('')}${active.id==='cash'?`<label>Forecast start month<input type="month" required data-key="start" value="${esc(values.start)}"></label><label>First expected collection date<input type="date" required data-key="first" value="${esc(values.first)}"></label><label>Second expected collection date<input type="date" required data-key="second" value="${esc(values.second)}"></label>`:''}</div><div id="validation" role="status"></div><div class="formula"><strong>How it works & assumptions</strong><br>${active.formula}<br>Fictional editable examples. USD. Estimates, not guarantees.</div></section><section class="panel results" aria-live="polite"><h2>Estimated results</h2><div id="results"></div><p class="result-note">${active.id==='capacity'?'Hours and capacity refer to the selected period.':'Based on the assumptions you enter.'} “Not attainable” means an undefined ratio or an unreachable target.</p></section></div>`;
app.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{values[el.dataset.key]=['date','month'].includes(el.type)?el.value:el.value===''?null:Number(el.value);persist();update()});document.querySelector('#reset').onclick=()=>{saved[active.id]=defaults(active);values=saved[active.id];persist();render();toast('Example assumptions restored')};document.querySelector('#copy').onclick=async()=>{if(!rows){toast('Correct the inputs before copying');return}let t=active.name+' — estimated results (USD)\n'+active.fields.map(f=>f.label+': '+fmt(values[f.key],f.unit)).join('\n')+'\n'+(active.id==='cash'?`Forecast: ${values.start}; collections: ${values.first}, ${values.second}\n`:'')+(active.id==='capacity'?`Period: ${values.period}\n`:'')+rows.map(([n,v,u])=>n+': '+fmt(v,u)).join('\n')+'\nAssumptions: '+active.formula;try{await navigator.clipboard.writeText(t);toast('Results copied')}catch{const area=document.createElement('textarea');area.className='copy-fallback';area.setAttribute('aria-label','Select and copy results');area.value=t;app.append(area);area.select();toast('Select and copy the results below')}};
if(active.id==='launch')document.querySelector('#preset').onchange=e=>{if(e.target.value){values.p=Number(e.target.value);persist();render()}};
if(active.id==='capacity')document.querySelector('#period').onchange=e=>{let ratio=e.target.value==='monthly'?52/12:12/52;for(let k of ['h','c','a','p'])values[k]*=ratio;values.period=e.target.value;persist();render()};calculatorIntegration(active,values,app.querySelector('.actions'));update();}
function enhance(){for(const f of active.fields.filter(f=>f.unit==='%')){const number=app.querySelector('[data-key='+f.key+']');const existing=number.parentElement.parentElement.querySelector('[type=range]');if(existing){existing.value=values[f.key];continue;}const slider=document.createElement('input');slider.type='range';slider.min=0;slider.max=100;slider.step=1;slider.value=values[f.key];slider.setAttribute('aria-label',f.label+' slider');slider.oninput=()=>{values[f.key]=Number(slider.value);number.value=slider.value;persist();update()};number.parentElement.parentElement.append(slider)}if(active.id==='leads'&&rows){let stage=rows.slice(0,4),max=Math.max(1,...stage.map(r=>r[1]));document.querySelector('#results').insertAdjacentHTML('beforeend','<div class=chart role=img aria-label='+String.fromCharCode(34)+'Expected funnel: '+stage.map(r=>r[0]+' '+fmt(r[1])).join(', ')+String.fromCharCode(34)+'>'+stage.map(r=>'<div class=bar title='+String.fromCharCode(34)+r[0]+': '+fmt(r[1])+String.fromCharCode(34)+' style='+String.fromCharCode(34)+'height:'+Math.max(3,r[1]/max*100)+'%'+String.fromCharCode(34)+'></div>').join('')+'</div>')}} function update(){const bad=[...app.querySelectorAll('input')].some(i=>i.value===''||!i.checkValidity());let msg=bad?'Enter valid values in all fields.':active.id==='cash'&&values.p+values.q>100?'Payment percentages cannot total more than 100%.':'';document.querySelector('#validation').innerHTML=msg?`<p class="error">${msg}</p>`:'';rows=msg?null:active.calculate(values);document.querySelector('#results').innerHTML=rows?rows.map(([n,v,u])=>`<div class="metric"><span>${n}</span><strong class="${v<0?'negative':''}">${fmt(v,u)}</strong></div>`).join('')+(active.id==='cash'?`<p class="result-note">${rows.slice(4).some(r=>r[1]<0)?'⚠ Cash shortfall projected. Review monthly collections and expenses.':'No month-end cash shortfall in this forecast.'}</p>`:''):'<p class="result-note">Correct the assumptions to calculate results.</p>';enhance();}
document.querySelector('#clear').onclick=async()=>{if(await ask('Clear ALL local calculator inputs, tool drafts, saved processes, and CRM records? This cannot be undone. Export backups first.')){try{clearNewData();localStorage.removeItem(key);saved={};render();toast('All local tool data cleared')}catch{toast('Browser storage could not be cleared. Check permissions and export a backup.')}}};window.onhashchange=()=>{render();window.scrollTo(0,0)};render();
